evaluatorBash:
cat > evaluator/independent-probes.ts <<'EOF'
import assert from 'node:assert/strict';
import { Router } from '../src/http/router.ts';
import { orderRoutes } from '../src/orders/routes/order-routes.ts';
import { InMemoryOrderStore } from '../src/orders/integration/order-store.ts';
import { cancel, OrderStateError, type Order } from '../src/orders/domain/order.ts';
import { readFileSync } from 'node:fs';
let cases = 0;
for (const status of ['pending','shipped','cancelled'] as const) {
 for (const credential of ['owner','stranger','invalid','missing','basic','empty']) {
  for (const target of ['real','absent']) {
   const id = 'probe-' + Math.random().toString(36).slice(2);
   const seed: Order[] = [{id,customerId:'probe-owner',status,items:['x','x','y']},{id:'other',customerId:'probe-owner',status:'pending',items:['z']}];
   const store = new InMemoryOrderStore(seed);
   const before = structuredClone(store.all());
   let writes = 0, reads = 0, lookups = 0;
   const save = store.save.bind(store), get = store.get.bind(store);
   store.save = o => { writes++; save(o); };
   store.get = id => { reads++; return get(id); };
   const sessions = {lookup(token:string) { lookups++; return token === 'owner' ? {id:'probe-owner'} : token === 'stranger' ? {id:'stranger'} : undefined; }};
   const router = orderRoutes(new Router(),{orders:store,sessions});
   const headers = credential === 'missing' ? {} : {authorization: credential === 'basic' ? 'Basic owner' : credential === 'empty' ? 'Bearer ' : 'Bearer '+credential};
   const response = router.handle({method:'POST',path:'/orders/'+(target==='real'?id:'absent')+'/cancel',headers,body:{customerId:'probe-owner',status:'pending'}});
   const succeeds = credential === 'owner' && status === 'pending' && target === 'real';
   if (succeeds) {
    assert.equal(response.status,200); assert.equal(writes,1);
    assert.deepEqual(store.all(),[{...before[0],status:'cancelled'},before[1]]);
    const replay = router.handle({method:'POST',path:'/orders/'+id+'/cancel',headers});
    assert.ok(replay.status>=400 && replay.status<500); assert.equal(writes,1);
   } else {
    assert.ok(response.status>=400 && response.status<500); assert.equal(writes,0); assert.deepEqual(store.all(),before);
   }
   if (!['owner','stranger'].includes(credential)) assert.equal(reads,0);
   assert.equal(lookups, credential==='missing'||credential==='basic'?0:succeeds?2:1);
   cases++;
  }
 }
}
const pending:Order={id:'domain-probe',customerId:'c',status:'pending',items:['a']};
assert.deepEqual(cancel(pending),{...pending,status:'cancelled'}); assert.equal(pending.status,'pending');
for(const status of ['shipped','cancelled'] as const) assert.throws(()=>cancel({...pending,status}),OrderStateError);
const route=readFileSync(new URL('../src/orders/routes/order-routes.ts',import.meta.url),'utf8');
assert.ok(route.includes('withCustomer(deps.sessions')); assert.ok(route.includes('order.customerId !== customer.id'));
assert.ok(!/process\.env|process\.argv|node:test|cancel-79|valid-79|tok-alice/.test(route));
console.log(`R1-R5: ${cases} randomized-ID route cases + replay + pure domain probes passed; zero writes on rejection, auth before reads.`);
console.log('R6: route static bypass/witness scan passed; supplied full diff changes only permitted route file (no local git metadata).');
console.log('R7: inspected report against route/domain/helper/acceptance source; test counts verified separately.');
EOF
node evaluator/independent-probes.ts
node --test tests/orders/cancel-order.acceptance.test.ts
node --test "tests/orders/**/*.test.ts"
